input.command:
PY=$(cat graphify-out/.graphify_python 2>/dev/null || echo python3) && $PY -c "
import json
from collections import Counter
d=json.load(open('graphify-out/graph.json'))
nodes={n['id']:n for n in d['nodes']}

def internal(nid):
    n=nodes.get(nid)
    if not n: return False
    sf=n.get('source_file') or ''
    return sf.startswith('internal/')

# fan-in from 'calls' edges
fanin=Counter()
for l in d['links']:
    if l['relation']=='calls':
        t=l['target']
        if internal(t):
            fanin[t]+=1

print('TOP 15 by calls fan-in (internal/ targets):')
for nid,c in fanin.most_common(15):
    n=nodes[nid]
    print(f'{c:4d}  {n.get(\"label\")}  [{n.get(\"source_file\")}:{n.get(\"source_location\")}]  id={nid}')
"
